import { performance } from 'node:perf_hooks';
import { readTerms,classifyInput,constitutionalFingerprint,sha256 } from './contract.mjs';
import { withWriterLock,loadState,appendEvent,newEpoch } from './state.mjs';
import { runProbe } from './probe.mjs';
import { preservePendingIntent,presentTermsState,authorizePreaccept,recordCompletedPreacceptAccess,canAccept,importPreacceptHandoff } from './admission.mjs';
import { transitionPure,bootstrapDecisionPure,nodeDispatchReceiptPure } from './runtime-core.mjs';
import { processActiveTurn } from './runtime-turn.mjs';
import { runtimeRootDescriptor } from './runtime-root-verified.mjs';
import { CHAT_BOOTSTRAP_DEADLINE_MS,readLocalMaterializationReceipt,totalDeadlineOk,validateChatBootstrapEvidence,validateTransferRemoteHistory,validateActivationContinuationReceipt } from './bootstrap-semantic.mjs';
import { DEADLINE_RESULT,canResumeActivation } from './deadline-integrity.mjs';
function bootstrapReceipt(state,termsDigest,fingerprint,probe,hostEngine,hostSurface,terminal,mode,evidence=null){const material={schema:'ikant-le-bootstrap-receipt/v2',epoch:state.epoch,terms_digest:termsDigest,constitutional_fingerprint:fingerprint,source_head:state.bootstrap?.source_head||evidence?.source_head||state.admission?.source_head||null,runtime_root_sha256:state.bootstrap?.runtime_root_sha256||evidence?.runtime_root_sha256||null,transfer_receipt_sha256:state.bootstrap?.transfer_receipt_sha256||evidence?.transfer_receipt_sha256||null,materialization_receipt_sha256:state.bootstrap?.materialization_receipt_sha256||evidence?.materialization_receipt_sha256||null,bootstrap_evidence_receipt_sha256:state.bootstrap?.bootstrap_evidence_receipt_sha256||evidence?.evidence_receipt_sha256||null,deadline_elapsed_ms:state.bootstrap?.deadline_elapsed_ms??evidence?.elapsed_before_runtime_ms??null,deadline_result:state.bootstrap?.deadline_result||evidence?.deadline_result||null,deadline_origin_receipt_sha256:state.bootstrap?.deadline_origin_receipt_sha256||evidence?.deadline_origin_receipt_sha256||null,acceptance_event_id:state.admission?.acceptance_event_id||null,remote_history_sha256:state.bootstrap?.remote_history_sha256||null,transfer_attempt_receipt_sha256:state.bootstrap?.transfer_attempt_receipt_sha256||null,activation_continuation_receipt_sha256:state.bootstrap?.activation_continuation_receipt_sha256||null,host_profile:{surface:hostSurface,engine:hostEngine},probe:{ok:Boolean(probe?.ok),node:probe?.node||null,fs:probe?.fs||null,crypto:probe?.crypto||null,clock:probe?.clock||null,artifact_sink:Boolean(probe?.artifact_sink),warm:Boolean(probe?.warm)},mode,terminal,host_constraints_precede_local_contract:true};return{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material)))};}
function recordNodeDispatch(state,input,hostSurface){const receipt=nodeDispatchReceiptPure(input,state,{hostSurface});const s=structuredClone(state);s.admission.last_node_dispatch_receipt=receipt.receipt_sha256;appendEvent('NODE_DISPATCH',s,'Human input entered the local Node runtime before any iKant response path.',{receipt});return{s,receipt};}
function human(text,code=0){return{stdout:text,code};}
function bootstrapOnlyPendingIntent(input){const init=new Set(['inizializza','inizializzazione','initialize','initialise','avvia','attiva','bootstrap']),env=new Set(['ambiente','runtime','ikant','ikant_le','sessione','session','locale','local','controllata','controlled']),structural=new Set(['il','lo','la','i','gli','le','un','una','di','del','della','per','e','and','the','a','an','please','pls','repo','repository']);const raw=String(input??'').normalize('NFKC').toLowerCase().replace(/https?:\/\/github\.com\/luke883i\/ikant_le(?:\.git)?/g,' ikant_le ').replace(/[^\p{L}\p{N}_]+/gu,' ').trim(),words=raw.split(/\s+/).filter(Boolean);return words.length>0&&words.some(w=>init.has(w))&&words.filter(w=>!init.has(w)&&!env.has(w)&&!structural.has(w)).length===0;}
function termsMessage(terms){return`${terms.text.trim()}\n\nTerms digest: ${terms.digest}\n\nSe accetti questi termini nella sessione corrente, rispondi esattamente: I ACCEPT`;}
export function runCommand(input,{candidate=null,hostEngine='motore host non dichiarato',hostSurface='LOCAL_NODE_CHAT_HOST',resourceGrants=[],probeRunner=runProbe,hostAcquisition=[],hostObservations=[],actionReceipt=null,postActionObservations=[],preacceptHandoff=null,postAcceptBootstrapEvidence=null,monotonicNow=()=>performance.now()}={}){const runtimeEnteredAt=monotonicNow();return withWriterLock(()=>{const terms=readTerms();const fingerprint=constitutionalFingerprint();let state=loadState();const kind=classifyInput(input);if(postAcceptBootstrapEvidence&&kind!=='ACCEPT')return human('Il post-accept bootstrap evidence può essere usato solo con lo stesso messaggio umano esatto I ACCEPT.',1);if(preacceptHandoff&&kind!=='ACCEPT')return human('Il pre-accept handoff può essere importato solo insieme allo stesso messaggio umano esatto I ACCEPT.',1);if(kind==='ACCEPT'&&preacceptHandoff){const imported=importPreacceptHandoff(state,preacceptHandoff,terms.digest);if(!imported.ok)return human(`Il pre-accept handoff non è valido (${imported.code}); iKant resta non-ACTIVE.`,1);state=imported.state;appendEvent('PREACCEPT_HANDOFF',state,'Host-observed pre-accept context imported into fresh local state without promoting acceptance, probe or initialization.',{handoff_sha256:imported.digest,source_head:imported.source_head,runtime_observed_terms_presentation:false,host_attested_terms_presentation:true,authority:0});}let dispatched=recordNodeDispatch(state,input,hostSurface);state=dispatched.s;const dispatch=dispatched.receipt;if(!dispatch.node20_plus)return human('L’ambiente corrente non dimostra Node.js 20 o superiore; iKant resta non-ACTIVE.',1);
for(const evt of hostAcquisition){if(state.accepted)break;if(evt.completed){const breach=recordCompletedPreacceptAccess(state,evt.action,{target:evt.target});if(breach.breached){state=breach.state;appendEvent('CAPSULE_BREACH',state,'Forbidden pre-accept repository acquisition completed; this chat cannot become a conforming iKant session.',{action:evt.action,target:evt.target||null});return human('Questa chat ha oltrepassato la capsula di orientamento prima dell’accettazione. Non posso sanarla retroattivamente come sessione iKant conforme: apri una nuova chat e inizializzala dal link canonico del repository.',1);}}else{const d=authorizePreaccept(state,evt.action,{target:evt.target,byteCount:evt.byteCount||0,metadataFields:evt.metadataFields||[]});if(!d.allowed)return human('La richiesta di acquisizione pre-accept è fuori dalla capsula consentita; il bootstrap resta fermo.',1);state=d.state;appendEvent('ORIENTATION',state,'Bounded pre-accept orientation operation allowed by capsule.',{action:evt.action,target:evt.target||null});}}
if(state.admission.breached||state.status==='SESSION_NONCONFORMING')return human('Questa chat è marcata non conforme per una rottura pre-accept della capsula. Per una sessione iKant conforme è necessaria una nuova chat.',1);
if(kind==='TERMS'){state=presentTermsState(state,terms.digest);appendEvent('TERMS_PRESENTED',state,'Current Terms were presented and pre-accept repository acquisition is now frozen.',{terms_digest:terms.digest});return human(termsMessage(terms));}
if(kind==='ACCEPT'){if(!canAccept(state,terms.digest))return human('L’accettazione non è valida finché i Terms correnti non sono stati presentati e legati a questa sessione. Chiedi TERMS o formula la tua richiesta: conserverò l’intento e mostrerò i Terms.',1);const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('L’ammissione non può essere riaperta in questo stato.',1);next.state.epoch=newEpoch();next.state.admission.acceptance_event_id=typeof postAcceptBootstrapEvidence?.acceptance_event_id==='string'?postAcceptBootstrapEvidence.acceptance_event_id:newEpoch();const declaredMode=postAcceptBootstrapEvidence?.transfer?.mode==='WARM_CACHE_EXACT'?'WARM':'COLD';appendEvent('ACCEPT',next.state,'Exact current-session Terms acceptance bound; automatic bootstrap authorized.',{bootstrap_mode:declaredMode,preaccept_handoff_sha256:state.admission.preaccept_handoff_sha256||null,source_head:state.admission.source_head||null,acceptance_event_id:next.state.admission.acceptance_event_id,acceptance_consumed:true});const root=runtimeRootDescriptor();const localMaterialization=readLocalMaterializationReceipt();const remoteHistory=validateTransferRemoteHistory(postAcceptBootstrapEvidence?.transfer,{sourceHead:next.state.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,runtimeRootDescriptor:root,maxReads:8,maxRounds:1,flexMaxReads:40,flexMaxRounds:1,deadlineMs:CHAT_BOOTSTRAP_DEADLINE_MS});if(remoteHistory.ok){next.state.bootstrap.remote_history_sha256=remoteHistory.remote_history_sha256;next.state.bootstrap.transfer_attempt_receipt_sha256=postAcceptBootstrapEvidence?.transfer?.receipt_sha256||null;}let evidence=validateChatBootstrapEvidence(postAcceptBootstrapEvidence,{sourceHead:next.state.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,loaderBlobSha1:root?.loader?.blob_sha1,localMaterializationReceipt:localMaterialization,runtimeRootDescriptor:root,termsDigest:terms.digest,maxReads:8,maxRounds:1,flexMaxReads:40,flexMaxRounds:1,deadlineMs:CHAT_BOOTSTRAP_DEADLINE_MS});let probe=null;if(evidence.ok)probe=probeRunner({warm:declaredMode==='WARM',hostSurface});const localElapsed=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(evidence.ok&&!totalDeadlineOk(evidence.elapsed_before_runtime_ms,localElapsed,CHAT_BOOTSTRAP_DEADLINE_MS))evidence={...evidence,ok:false,terminal:'BOOTSTRAP_DEADLINE_EXCEEDED',deadline_result:DEADLINE_RESULT.EXCEEDED,errors:['e2e_deadline']};const decision=bootstrapDecisionPure(next.state,terms.digest,fingerprint,probe,{hostSurface,hostEngine,evidenceValidation:evidence});if(decision.terminal!=='ACTIVE'){const receipt=bootstrapReceipt(decision.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,decision.terminal,decision.mode,evidence);decision.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',decision.state,'Automatic post-accept bootstrap did not reach ACTIVE; no false activation permitted.',{receipt,evidence_errors:evidence.errors||[]});return human(decision.state.bootstrap?.availability?.business_summary||'Non posso dichiararmi attivo: una verifica necessaria del bootstrap non è stata superata. La sessione resta non-ACTIVE.',1);}let evidenced=structuredClone(next.state);evidenced.bootstrap={...decision.state.bootstrap,terminal:'EVIDENCE_VERIFIED',probe:null};evidenced.status='ACCEPTED';evidenced.probed=false;evidenced.initialized=false;appendEvent('BOOTSTRAP_EVIDENCE',evidenced,'Source-bound transfer and transfer-bound local materialization were verified before the live host probe.',{source_head:evidence.source_head,runtime_root_sha256:evidence.runtime_root_sha256,transfer_receipt_sha256:evidence.transfer_receipt_sha256,materialization_receipt_sha256:evidence.materialization_receipt_sha256,evidence_receipt_sha256:evidence.evidence_receipt_sha256,authority:0});let probed=transitionPure(evidenced,'PROBE',terms.digest,true).state;probed.bootstrap={...evidenced.bootstrap,terminal:'PROBED',probe};appendEvent('PROBE',probed,'Automatic local Node probe passed with real readback.',{node:probe.node,fs:probe.fs,warm:declaredMode==='WARM',host_surface:hostSurface});const beforeCommit=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(!totalDeadlineOk(evidence.elapsed_before_runtime_ms,beforeCommit,CHAT_BOOTSTRAP_DEADLINE_MS)){probed.status='ADMISSION_EPOCH_UNRECOVERABLE';probed.probed=false;probed.initialized=false;probed.admission.new_chat_required=true;probed.bootstrap={...probed.bootstrap,evidence_verified:false,terminal:'ADMISSION_EPOCH_UNRECOVERABLE',deadline_result:DEADLINE_RESULT.EXCEEDED,deadline_terminal:DEADLINE_RESULT.EXCEEDED,deadline_elapsed_ms:evidence.elapsed_before_runtime_ms+beforeCommit};const receipt=bootstrapReceipt(probed,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ADMISSION_EPOCH_UNRECOVERABLE',declaredMode,{...evidence,deadline_result:DEADLINE_RESULT.EXCEEDED});probed.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',probed,'The I ACCEPT to ACTIVE deadline was exceeded before the ACTIVE commit.',{receipt});return human('ADMISSION_EPOCH_UNRECOVERABLE — il deadline end-to-end è stato superato; questa admission non può essere riaperta. Serve una nuova chat.',1);}let active=transitionPure(probed,'INITIALIZE',terms.digest).state;active.bootstrap={...probed.bootstrap,terminal:'ACTIVE',deadline_elapsed_ms:evidence.elapsed_before_runtime_ms+beforeCommit};const receipt=bootstrapReceipt(active,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ACTIVE',declaredMode,evidence);active.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('INITIALIZE',active,'Automatic iKant epoch initialization completed after verified source transfer, local materialization and live host probe.',{receipt});const pending=active.admission.pending_intent;if(pending){active.admission.pending_intent=null;if(bootstrapOnlyPendingIntent(pending)){appendEvent('PENDING_INTENT_FULFILLED_BY_ACTIVE',active,'The preserved request was pure bootstrap control and is satisfied by the ACTIVE transition without creating a synthetic substantive turn.',{pending_intent_sha256:active.admission.pending_intent_sha256,authority:0});return human('iKant è attivo. L’intento di inizializzazione è stato soddisfatto dalla transizione ACTIVE; non viene creato un turno cognitivo artificiale.');}appendEvent('PENDING_INTENT_RESUME',active,'The original substantive request is resumed automatically after successful admission.',{pending_intent_sha256:active.admission.pending_intent_sha256});const pd=recordNodeDispatch(active,pending,hostSurface);return processActiveTurn(pd.s,pending,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,pd.receipt,{resumed:true}).out;}return human('iKant è attivo. La shell narrativa è pronta; ogni prossimo input passerà dal runtime Node e il dettaglio tecnico resterà nel backlog DOCX.');}
if(kind==='PROBE'){if(state.status==='ACTIVE')return human('Il probe automatico di questa epoch risulta già superato; nessun nuovo gate è necessario.');if(state.bootstrap?.evidence_verified!==true||state.bootstrap?.deadline_terminal||state.admission?.new_chat_required===true)return human('Probe diagnostico negato: l’admission non possiede evidence recuperabile o ha un terminale deadline sticky. Serve una nuova chat per una nuova admission.',1);const probe=probeRunner({warm:false,hostSurface});const next=transitionPure(state,kind,terms.digest,probe.ok);if(next.terminal==='DENY')return human('Probe diagnostico negato: serve prima una accettazione valida dei Terms correnti.');if(next.terminal==='DEGRADED'){appendEvent('PROBE_FAILURE',next.state,'Diagnostic probe failed; runtime availability is DEGRADED and iKant remains non-ACTIVE.',{reason:probe.reason});return human('DEGRADED — una capacita host obbligatoria non e disponibile. Non garantito: esecuzione runtime conforme, attivazione iKant. Recupero: ripristinare il probe live richiesto e ripetere la verifica.',1);}next.state.bootstrap={...next.state.bootstrap,probe,terminal:'PROBED'};appendEvent('PROBE',next.state,'Diagnostic recovery probe passed.',{node:probe.node});return human('Probe diagnostico superato. Se questa è una recovery manuale, INITIALIZE IKANT può completare l’epoch.');}
if(kind==='INITIALIZE'){if(state.status==='ACTIVE')return human('L’inizializzazione automatica di questa epoch risulta già completata.');if(state.bootstrap?.evidence_verified!==true||state.bootstrap?.deadline_terminal||state.admission?.new_chat_required===true)return human('Inizializzazione diagnostica negata: evidence assente oppure terminale deadline sticky. Serve una nuova chat.',1);const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('Inizializzazione diagnostica negata: accettazione e probe correnti devono risultare validi.');next.state.bootstrap={...next.state.bootstrap,terminal:'ACTIVE',fingerprint};appendEvent('INITIALIZE',next.state,'Diagnostic recovery initialization completed.');return human('iKant è attivo.');}
if(kind==='EXIT'){const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('EXIT IKANT non ha effetto perché iKant non risulta ACTIVE.');appendEvent('EXIT',next.state,'Human requested exact iKant exit.');return human('Modalità iKant chiusa. Per rientrare serve una nuova accettazione esatta dei Terms correnti.');}
if(kind==='PREFERENCE'){const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('Preferenza non registrata: iKant non è ACTIVE.');next.state.preference=input.slice('PREFER '.length);appendEvent('PREFERENCE',next.state,'Explicit reversible verbosity preference updated.');return human(`Preferenza esplicita impostata su ${next.state.preference}.`);}
if(state.status!=='ACTIVE'){if(!state.admission.terms_presented){state=preservePendingIntent(state,input);state=presentTermsState(state,terms.digest);appendEvent('PENDING_INTENT',state,'The first substantive request is preserved while admission pauses execution.',{pending_intent_sha256:state.admission.pending_intent_sha256});appendEvent('TERMS_PRESENTED',state,'Current Terms were presented and pre-accept repository acquisition is now frozen.',{terms_digest:terms.digest});return human(termsMessage(terms));}if(!state.admission.pending_intent){state=preservePendingIntent(state,input);appendEvent('PENDING_INTENT',state,'A substantive request was preserved while awaiting exact acceptance.',{pending_intent_sha256:state.admission.pending_intent_sha256});}return human('I Terms correnti sono già stati presentati. Per continuare nella stessa sessione rispondi esattamente: I ACCEPT');}
const r=processActiveTurn(state,input,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,dispatch);return r.out;});}

export function resumeActivation({candidate=null,hostEngine='motore host non dichiarato',hostSurface='LOCAL_NODE_CHAT_HOST',resourceGrants=[],probeRunner=runProbe,hostObservations=[],actionReceipt=null,postActionObservations=[],postAcceptBootstrapEvidence=null,monotonicNow=()=>performance.now()}={}){const runtimeEnteredAt=monotonicNow();return withWriterLock(()=>{const terms=readTerms(),fingerprint=constitutionalFingerprint();let state=loadState();if(!canResumeActivation(state))return human('Recovery same-epoch non disponibile: admission non recuperabile o binding incompleti.',1);if(!postAcceptBootstrapEvidence)return human('Recovery same-epoch negata: manca il bootstrap evidence aggiornato.',1);if(postAcceptBootstrapEvidence.acceptance_event_id!==state.admission.acceptance_event_id||postAcceptBootstrapEvidence.acceptance_origin_receipt_sha256!==state.bootstrap.deadline_origin_receipt_sha256)return human('Recovery same-epoch negata: acceptance binding incompatibile.',1);const root=runtimeRootDescriptor();const history=validateTransferRemoteHistory(postAcceptBootstrapEvidence.transfer,{sourceHead:state.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,runtimeRootDescriptor:root,maxReads:8,maxRounds:1,flexMaxReads:40,flexMaxRounds:1,deadlineMs:CHAT_BOOTSTRAP_DEADLINE_MS});if(!history.ok||history.remote_history_sha256!==state.bootstrap.remote_history_sha256)return human('Recovery same-epoch negata: remote acquisition history diversa o non valida.',1);const continuation=validateActivationContinuationReceipt(postAcceptBootstrapEvidence.activation_continuation,{sourceHead:state.admission.source_head,termsDigest:terms.digest,acceptanceEventId:state.admission.acceptance_event_id,acceptanceOriginReceiptSha256:state.bootstrap.deadline_origin_receipt_sha256,remoteHistorySha256:state.bootstrap.remote_history_sha256,minElapsedMs:state.bootstrap.deadline_elapsed_ms,deadlineMs:CHAT_BOOTSTRAP_DEADLINE_MS});if(!continuation.ok){if(continuation.deadline_result===DEADLINE_RESULT.EXCEEDED){state.status='ADMISSION_EPOCH_UNRECOVERABLE';state.probed=false;state.initialized=false;state.admission.new_chat_required=true;state.bootstrap={...state.bootstrap,evidence_verified:false,terminal:'ADMISSION_EPOCH_UNRECOVERABLE',deadline_result:DEADLINE_RESULT.EXCEEDED,deadline_terminal:DEADLINE_RESULT.EXCEEDED,activation_continuation_receipt_sha256:postAcceptBootstrapEvidence.activation_continuation?.receipt_sha256||null};appendEvent('BOOTSTRAP_FAILURE',state,'Same-epoch activation continuation observed the end-to-end deadline exceeded.',{acceptance_event_id:state.admission.acceptance_event_id});return human('ADMISSION_EPOCH_UNRECOVERABLE — il deadline end-to-end è stato superato durante la continuation.',1);}return human('Recovery same-epoch negata: continuation receipt mancante o invalida.',1);}let working=structuredClone(state);working.bootstrap={...working.bootstrap,remote_history_sha256:history.remote_history_sha256,transfer_attempt_receipt_sha256:postAcceptBootstrapEvidence.transfer?.receipt_sha256||null,activation_continuation_receipt_sha256:continuation.receipt_sha256,deadline_elapsed_ms:continuation.elapsed_before_runtime_ms};const localMaterialization=readLocalMaterializationReceipt();let evidence=validateChatBootstrapEvidence(postAcceptBootstrapEvidence,{sourceHead:working.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,loaderBlobSha1:root?.loader?.blob_sha1,localMaterializationReceipt:localMaterialization,runtimeRootDescriptor:root,termsDigest:terms.digest,maxReads:8,maxRounds:1,flexMaxReads:40,flexMaxRounds:1,deadlineMs:CHAT_BOOTSTRAP_DEADLINE_MS,elapsedBeforeRuntimeMsOverride:continuation.elapsed_before_runtime_ms});let probe=null;if(evidence.ok)probe=probeRunner({warm:postAcceptBootstrapEvidence?.transfer?.mode==='WARM_CACHE_EXACT',hostSurface});const localElapsed=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(evidence.ok&&!totalDeadlineOk(evidence.elapsed_before_runtime_ms,localElapsed,CHAT_BOOTSTRAP_DEADLINE_MS))evidence={...evidence,ok:false,terminal:'BOOTSTRAP_DEADLINE_EXCEEDED',deadline_result:DEADLINE_RESULT.EXCEEDED,errors:['e2e_deadline']};const decision=bootstrapDecisionPure(working,terms.digest,fingerprint,probe,{hostSurface,hostEngine,evidenceValidation:evidence});if(decision.terminal!=='ACTIVE'){const receipt=bootstrapReceipt(decision.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,decision.terminal,decision.mode,evidence);decision.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',decision.state,'Same-epoch activation continuation did not reach ACTIVE; no acceptance, origin, epoch or remote-history reset occurred.',{receipt,evidence_errors:evidence.errors||[],continuation_receipt_sha256:continuation.receipt_sha256,remote_history_sha256:history.remote_history_sha256});return human(decision.state.bootstrap?.availability?.business_summary||'Recovery same-epoch incompleta; iKant resta non-ACTIVE.',1);}appendEvent('ACTIVATION_RESUME',working,'Same-epoch activation continuation accepted without new human acceptance or remote acquisition.',{acceptance_event_id:working.admission.acceptance_event_id,continuation_receipt_sha256:continuation.receipt_sha256,remote_history_sha256:history.remote_history_sha256,authority:0});let evidenced=structuredClone(working);evidenced.bootstrap={...decision.state.bootstrap,terminal:'EVIDENCE_VERIFIED',probe:null,remote_history_sha256:history.remote_history_sha256,activation_continuation_receipt_sha256:continuation.receipt_sha256};evidenced.status='ACCEPTED';evidenced.probed=false;evidenced.initialized=false;appendEvent('BOOTSTRAP_EVIDENCE',evidenced,'Same-epoch source-bound transfer and local materialization were verified after host capability recovery.',{source_head:evidence.source_head,runtime_root_sha256:evidence.runtime_root_sha256,transfer_receipt_sha256:evidence.transfer_receipt_sha256,materialization_receipt_sha256:evidence.materialization_receipt_sha256,evidence_receipt_sha256:evidence.evidence_receipt_sha256,continuation_receipt_sha256:continuation.receipt_sha256,remote_history_sha256:history.remote_history_sha256,authority:0});let probed=transitionPure(evidenced,'PROBE',terms.digest,true).state;probed.bootstrap={...evidenced.bootstrap,terminal:'PROBED',probe};appendEvent('PROBE',probed,'Same-epoch recovery probe passed with real readback.',{node:probe.node,fs:probe.fs,host_surface:hostSurface});const beforeCommit=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(!totalDeadlineOk(evidence.elapsed_before_runtime_ms,beforeCommit,CHAT_BOOTSTRAP_DEADLINE_MS)){probed.status='ADMISSION_EPOCH_UNRECOVERABLE';probed.probed=false;probed.initialized=false;probed.admission.new_chat_required=true;probed.bootstrap={...probed.bootstrap,evidence_verified:false,terminal:'ADMISSION_EPOCH_UNRECOVERABLE',deadline_result:DEADLINE_RESULT.EXCEEDED,deadline_terminal:DEADLINE_RESULT.EXCEEDED,deadline_elapsed_ms:evidence.elapsed_before_runtime_ms+beforeCommit};const receipt=bootstrapReceipt(probed,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ADMISSION_EPOCH_UNRECOVERABLE',decision.mode,{...evidence,deadline_result:DEADLINE_RESULT.EXCEEDED});probed.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',probed,'The original I ACCEPT to ACTIVE deadline was exceeded before the recovery ACTIVE commit.',{receipt});return human('ADMISSION_EPOCH_UNRECOVERABLE — deadline superato prima del commit ACTIVE.',1);}let active=transitionPure(probed,'INITIALIZE',terms.digest).state;active.bootstrap={...probed.bootstrap,terminal:'ACTIVE',deadline_result:DEADLINE_RESULT.PASS,deadline_terminal:null,deadline_elapsed_ms:evidence.elapsed_before_runtime_ms+beforeCommit};const receipt=bootstrapReceipt(active,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ACTIVE',decision.mode,evidence);active.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('INITIALIZE',active,'Same-epoch activation recovery completed after preserved acceptance/source/remote history and verified downstream gates.',{receipt});const pending=active.admission.pending_intent;if(pending){active.admission.pending_intent=null;if(bootstrapOnlyPendingIntent(pending)){appendEvent('PENDING_INTENT_FULFILLED_BY_ACTIVE',active,'The preserved bootstrap-only intent is satisfied by recovered ACTIVE.',{pending_intent_sha256:active.admission.pending_intent_sha256,authority:0});return human('iKant è attivo. La recovery ha preservato acceptance, epoch, source e deadline origin.');}appendEvent('PENDING_INTENT_RESUME',active,'The original substantive request is resumed once after recovered ACTIVE.',{pending_intent_sha256:active.admission.pending_intent_sha256});const pd=recordNodeDispatch(active,pending,hostSurface);return processActiveTurn(pd.s,pending,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,pd.receipt,{resumed:true}).out;}return human('iKant è attivo. Recovery same-epoch completata senza nuova acceptance.');});}

import fs from 'node:fs';
import crypto from 'node:crypto';

function crc32(buf) {
  let c = 0xffffffff;
